const token=prompt('Enter the admin token'),auth={Authorization:'Bearer '+token,'Content-Type':'application/json'},$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function req(u,b){const r=await fetch(u,{method:b?'POST':'GET',headers:auth,body:b?JSON.stringify(b):undefined}),d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}async function render(){try{const d=await req('/api/admin/status'),p=d.meta.feed_paused==='true',f=d.file;$('#export-dir').value='RACE_EXPORT_DIR='+d.sourceConfig.hostDirectory;$('#export-filename').value='RACE_EXPORT_FILENAME='+d.sourceConfig.filename;$('#app-version').textContent='Version '+d.version;$('#file-status').textContent=f.exists?`Reading ${f.configured} · ${f.bytes} bytes`:`Waiting for ${f.configured}`;$('#import-status').textContent=d.meta.last_error?'Last error: '+d.meta.last_error:'Last successful import: '+(d.meta.last_import||'waiting');$('#event-status').value=d.meta.status||'Live';$('#event-status').onchange=()=>req('/api/admin/status',{status:$('#event-status').value});$('#feed-toggle').textContent=p?'Start live updates':'Stop live updates ('+d.pollSeconds+'s)';$('#feed-toggle').onclick=async()=>{await req('/api/admin/feed',{running:p});render()};let m=$('#manage');if(!m){m=document.createElement('div');m.id='manage';$('#event-list').before(m)}m.innerHTML=`<h2>Tournaments and races</h2><input id="new-tournament" placeholder="New tournament"><button class="btn" id="add-tournament">Add tournament</button><select id="race-tournament">${d.tournaments.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><input id="new-race" placeholder="New race"><button class="btn" id="add-race">Add race</button>`;$('#add-tournament').onclick=async()=>{await req('/api/admin/tournaments',{name:$('#new-tournament').value});render()};$('#add-race').onclick=async()=>{await req('/api/admin/races',{tournamentId:+$('#race-tournament').value,name:$('#new-race').value});render()};const opts=d.races.map(r=>{const t=d.tournaments.find(t=>t.id===r.tournament_id);return `<option value="${r.id}">${esc((t?.name||'')+' — '+r.name)}</option>`}).join('');$('#event-list').innerHTML=d.events.map(e=>`<div class="event-row"><div><h3>${esc(e.name)}</h3><p>${e.count} imported results</p><select data-race="${esc(e.id)}"><option value="">Assign to a race…</option>${opts}</select><button class="btn assign" data-id="${esc(e.id)}">Assign</button></div><label class="switch"><input type="checkbox" data-visible="${esc(e.id)}" ${e.visible?'checked':''}><span class="slider"></span></label></div>`).join('');$('#event-list').querySelectorAll('[data-visible]').forEach(x=>x.onchange=async()=>{await req('/api/admin/events/'+encodeURIComponent(x.dataset.visible),{visible:x.checked});render()});$('#event-list').querySelectorAll('.assign').forEach(b=>b.onclick=async()=>{const r=d.races.find(x=>x.id===+$('#event-list').querySelector('[data-race="'+CSS.escape(b.dataset.id)+'"]').value),t=d.tournaments.find(x=>x.id===r.tournament_id);await req('/api/admin/events/'+encodeURIComponent(b.dataset.id),{mapping:true,tournament:t.name,stage:r.name,name:b.closest('.event-row').querySelector('h3').textContent});render()})}catch(e){$('#event-list').textContent=e.message}}render();

